+  const flags: string[] = [];
+  const targets: string[] = [];
+  let endOfOptions = false;
+  for (const w of args) {
+    if (!endOfOptions && w === '--') endOfOptions = true;
+    else if (!endOfOptions && w.startsWith('-')) flags.push(w);
+    else targets.push(w);
+  }
+  const recursive = flags.some((f) => f === '--recursive' || shortGroup(f, 'r') || shortGroup(f, 'R'));
+  if (!recursive) return undefined;
