+    let i = 0;
+    while (i < args.length && args[i].startsWith('-')) i += GIT_VALUE_OPTS.has(args[i]) ? 2 : 1;
+    const sub = args[i];
+    const rest = args.slice(i + 1);
+    const shortGroup = (w: string, letters: string) => /^-[^-]/.test(w) && [...letters].some((c) => w.includes(c));
+
+    if (sub === 'push') {
+      const bad = rest.some(
+        (w) =>
+          PUSH_FLAGS.has(w.split('=')[0]) ||
+          shortGroup(w, 'fd') ||
+          (!w.startsWith('-') && (w.startsWith('+') || w.startsWith(':'))),
+      );
+      return bad ? { name: 'force-push', reason: 'force push or remote deletion' } : undefined;
+    }
+    if (sub === 'reset' && rest.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards changes' };
+    if (sub === 'clean' && !rest.some((w) => w === '-n' || w === '--dry-run')) {
+      if (rest.includes('--force') || rest.some((w) => shortGroup(w, 'f')))
+        return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+    }
+    return undefined;
+  }
+
+  if (cmd === 'rm') {
+    const end = args.indexOf('--');
+    const flags = end < 0 ? args : args.slice(0, end);
+    const recursive = flags.some((w) => w === '--recursive' || /^-[^-]*[rR]/.test(w));
+    if (!recursive) return undefined;
+    const targets = args.filter((w, i) => (end >= 0 && i > end) || (end !== i && !w.startsWith('-')));
+    if (targets.length === 0) return outside('rm -r without targets');
+    for (const t of targets) if (!inWorkspace(t, cwd) || sameDir(t, cwd)) return outside(`rm -r ${t}`);
+    return undefined;
+  }
+
+  if (cmd === 'find' && args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) {
+    const firstFlag = args.findIndex((w) => w.startsWith('-'));
+    const starts = firstFlag < 0 ? args : args.slice(0, firstFlag);
+    for (const p of starts.length ? starts : ['.']) if (!inWorkspace(p, cwd)) return outside(`find ${p}`);
+    return undefined;
+  }
