+
+  const windowsWhere = (same: (a: string, b: string) => boolean) => {
+    const found: number[] = [];
+    for (let i = 0; i + oldLines.length <= lines.length; i++) {
+      if (oldLines.every((o, k) => same(lines[i + k], o))) found.push(i);
+    }
+    return found;
