+  }
+  if (trailing.length === 1) {
+    const i = trailing[0];
+    return { content: splice(i, newLines), applied: { from: i + 1, to: i + oldLines.length, tier: 'trailing-space', count: 1 } };
+  }
+
+  // 3. whole lines, ignoring indentation; new_text is re-indented to the matched window
+  const indented = windowsWhere((a, b) => a.trim() === b.trim());
+  if (indented.length > 1) {
+    return { error: `old_text matches ${indented.length} places (lines ${lineList(indented)}); add more context` };
+  }
+  if (indented.length === 1) {
+    const i = indented[0];
+    const indentOf = (s: string) => s.match(/^\s*/)![0];
+    const oldIndent = indentOf(oldLines.find((l) => l.trim() !== '')!);
+    const windowIndent = indentOf(lines.slice(i, i + oldLines.length).find((l) => l.trim() !== '')!);
