+      if (l.trim() === '') return '';
+      const rest = l.startsWith(oldIndent) ? l.slice(oldIndent.length) : l.trimStart();
+      return windowIndent + rest;
+    });
+    return { content: splice(i, reindented), applied: { from: i + 1, to: i + oldLines.length, tier: 'indentation', count: 1 } };
+  }
