+import type { EventOf, SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. Pure: it reads a change set, never the model. A finding is a flag, not a refusal.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const TEST_PATH = /(\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_)/;
+const PROSE = /\.(md|mdx|txt|rst)$/i;
+const ASSERT = /\bexpect\(|\bassert\w*\b|\bt\.(Error|Fatal)/;
+const SKIP = /\b(test|it|describe)\.skip\(|\b(xit|xtest|xdescribe)\(|\bt\.Skip(Now)?\(|\bpytest\.skip\(|@(pytest\.mark\.skip|unittest\.skip)\b/;
+const SUPPRESS = /@ts-ignore|@ts-expect-error|eslint-disable|# type: ignore|# noqa|# pylint: disable|#nosec|\/\/ nolint/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b/;
+const STUB = /not implemented|NotImplementedError|\bunimplemented!|\btodo!\(\)/i;
+
+// Line rules apply to code only: prose may say "as any" or "catch {}" without meaning it.
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', SUPPRESS],
+  ['swallowed-error', SWALLOW],
+  ['type-escape', TYPE_ESCAPE],
+  ['stub', STUB],
+];
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const test = TEST_PATH.test(c.path);
+    if (test && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (test && !c.deleted && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    if (test) for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path, line: l.trim() });
+    if (c.deleted || PROSE.test(c.path)) continue;
+    for (const l of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, line: l.trim() });
+  }
+  return out;
+}
+
+export const flagOf = (f: SlopFinding) => (f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
