+// Parses a `git diff -p -U0` patch. Lines count only inside a hunk, so `---`/`+++` headers are not content.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const l of patch.split('\n')) {
+    if (l.startsWith('diff --git ')) {
+      cur = { path: /^diff --git a\/.* b\/(.*)$/.exec(l)?.[1] ?? l, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (l.startsWith('deleted file mode')) cur.deleted = true;
+    else if (l.startsWith('@@')) inHunk = true;
+    else if (inHunk && l.startsWith('+')) cur.added.push(l.slice(1));
+    else if (inHunk && l.startsWith('-')) cur.removed.push(l.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, the changes are the completed edit and write calls in the run's events.
+export function changesFromEvents(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  const lines = (s: unknown) => String(s ?? '').split('\n');
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const i = intents.get(e.callId);
+    if (!i) continue;
+    const path = String(i.input.path ?? '');
+    if (i.tool === 'write') out.push({ path, added: lines(i.input.content), removed: [], deleted: false });
+    else if (i.tool === 'edit') {
+      const edits = Array.isArray(i.input.edits) ? (i.input.edits as { old_text?: unknown; new_text?: unknown }[]) : [];
+      out.push({ path, added: edits.flatMap((x) => lines(x.new_text)), removed: edits.flatMap((x) => lines(x.old_text)), deleted: false });
+    }
+  }
