+// Shortcuts that make work look done. Pure: it reads a run's changes, never the model. Each finding names a
+// rule, the file, and for line rules the added line that matched.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|cs|swift|php|c|cc|cpp|h|hpp)$/;
+const TEST_PATH = /(^|\/)(tests?|__tests__)\/|[._-](test|spec)\.[^/]+$|(^|\/)test_[^/]*$/;
+const ASSERT = /\b(assert\w*|expect)\b|\.should\b|\.to\w*\(/;
+const SKIP = /\b(test|it|describe)\.skip\b|\bxit\(|\bxdescribe\(|\bit\.todo\b|\bt\.Skip\(|pytest\.skip|@pytest\.mark\.skip|@Ignore\b/;
+const SUPPRESS = /@ts-(ignore|nocheck|expect-error)|eslint-disable|# type: ignore|# noqa|\bnolint\b|#\[allow\(|pylint: disable|@SuppressWarnings/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|\bexcept\b[^:]*:\s*pass\b/;
+const TYPE_ESCAPE = /\bas any\b|<any>/;
+const STUB = /not implemented|NotImplementedError|\btodo!\(|\bunimplemented!\(/i;
+
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', SUPPRESS],
+  ['swallowed-error', SWALLOW],
+  ['type-escape', TYPE_ESCAPE],
+  ['stub', STUB],
+];
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const test = TEST_PATH.test(c.path);
+    if (test && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (test && !c.deleted && c.removed.filter((l) => ASSERT.test(l)).length > c.added.filter((l) => ASSERT.test(l)).length)
+      out.push({ rule: 'test-weakened', path: c.path });
+    if (test) for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path, line: l.trim() });
+    if (!CODE.test(c.path) || c.deleted) continue;
+    for (const l of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, line: l.trim() });
+  }
+  return out;
+}
+
+export const flagOf = (f: SlopFinding) => (f.line ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
+
+// Reads a `git diff-tree -p -U0` patch. Hunk counts say how many lines follow, so a removed line that starts
+// with `--` is not taken for a file header.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let left = { old: 0, new: 0 };
+  for (const line of patch.split('\n')) {
+    if (left.old > 0 || left.new > 0) {
+      if (line.startsWith('+') && left.new > 0) cur!.added.push(line.slice(1)), left.new--;
+      else if (line.startsWith('-') && left.old > 0) cur!.removed.push(line.slice(1)), left.old--;
+      else if (line.startsWith(' ')) left.old--, left.new--;
+      continue;
+    }
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+    } else if (cur && line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (cur && line.startsWith('@@')) {
+      const m = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/.exec(line)!;
+      left = { old: m[2] === undefined ? 1 : Number(m[2]), new: m[4] === undefined ? 1 : Number(m[4]) };
+    }
+  }
