+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('10 units get 5% off the line', () => {
+    // 10 pens = 1200; 5% off = 60 -> 1140; shipping 800; tax 7% of 1940 = 135.8 -> 136
+    expect(totals(cart('US', [['PEN', 10]]))).toMatchObject({ subtotal: 1140, shipping: 800, tax: 136, total: 2076 });
+  });
+
+  test('50 units get 10% off the line', () => {
+    // 50 pens = 6000; 10% off = 600 -> 5400 >= 5000 ships free; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('bulk tier counts units per SKU across lines', () => {
+    // 6 + 4 mugs = 10 units -> 5% of 4500 = 225 -> 4275; shipping 800 (below 5000); tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 4]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('shipping threshold uses the subtotal after coupon', () => {
+    // 4 caps = 4800 (below US 5000 anyway); use 5 caps = 6000 with SAVE10 -> 5400 >= 5000 ships free
+    // tax 7% of 5400 = 378
+    expect(totals(cart('US', [['CAP', 5]], 'SAVE10'))).toMatchObject({ subtotal: 6000, coupon: 600, shipping: 0, total: 5778 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000 ships free; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ shipping: 0, tax: 880, total: 5280 });
+  });
+});

