+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+describe('pricing rules from README', () => {
+  test('bulk discount applies at exactly 10 units', () => {
+    // 10 mugs = 4500; 5% off = 225 -> 4275; shipping 800 (< 5000); tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, coupon: 0, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('bulk discount applies at exactly 50 units', () => {
+    // 50 mugs = 22500; 10% off = 2250 -> 20250; free shipping; tax 7% of 20250 = 1417.5 -> 1418
+    expect(totals(cart('US', [['MUG', 50]]))).toMatchObject({ subtotal: 20250, shipping: 0, tax: 1418, total: 21668 });
+  });
+
+  test('lines of the same SKU are merged before bulk pricing', () => {
+    // 6 + 4 mugs = 10 units -> 5% off
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 4]])).subtotal).toBe(4275);
+    expect(totals(cart('US', [['MUG', 6], ['MUG', 4]])).lines).toHaveLength(1);
