+    expect(t.tax).toBe(Math.floor(4600 * 0.2 + 0.5));
+  });
+
+  test('UK free shipping threshold is 4000', () => {
+    expect(totals(cart('UK', [['BAG', 2]])).shipping).toBe(0);
+  });
+});

